/* ---------- batch six ---------- */
#c57 .stage{min-height:520px}
.bt{display:inline-flex;align-items:center;justify-content:center;gap:8px;height:38px;padding:0 16px;font-family:var(--sans);font-size:13.5px;font-weight:600;border:1px solid transparent;white-space:nowrap;transition:background-color .2s ease,border-color .2s ease,color .2s ease,transform .15s ease,box-shadow .2s ease,opacity .2s ease}
.bt:active:not(:disabled){transform:scale(.97)}
.bt:focus-visible{outline:none;box-shadow:0 0 0 3px var(--accent-bg);border-color:var(--accent)}
.bt-primary{background:var(--accent-hi);color:#120a02}
.bt-primary:hover:not(:disabled){background:var(--accent)}
.bt-secondary{background:var(--panel);border-color:var(--icon-line);color:var(--text)}
.bt-secondary:hover:not(:disabled){border-color:var(--text-dim)}
.bt-ghost{background:transparent;color:var(--text)}
.bt-ghost:hover:not(:disabled){background:var(--chip)}
.bt-danger{background:rgba(255,90,95,.08);border-color:rgba(255,90,95,.3);color:var(--danger)}
.bt-danger:hover:not(:disabled){background:rgba(255,90,95,.14)}
.bt-sm{height:30px;padding:0 11px;font-size:12.5px;gap:6px}
.bt-lg{height:46px;padding:0 22px;font-size:15px}
.bt-icon{width:38px;padding:0}
.bt:disabled{opacity:.45;cursor:not-allowed}
.bt.ok{background:var(--success);color:#fff;border-color:var(--success)}
.bt-spin{display:inline-block;width:14px;height:14px;flex:none;border:2px solid currentColor;border-right-color:transparent;border-radius:50%;animation:spin .8s linear infinite}
.bt-ic{display:inline-grid;place-items:center;width:16px;height:16px}

/* reactions */
.rx{padding:16px 16px 6px;overflow:visible!important}
.rx-top{display:flex;align-items:center;gap:10px}
.rx-top .dz-av{width:38px;height:38px}
.rx-n{font-size:14px;font-weight:600}
.rx-m{font-size:12.5px;color:var(--muted)}
.rx-body{margin:12px 0 12px;font-size:14px;line-height:1.6;color:var(--text)}
.rx-sum{display:flex;align-items:center;gap:8px;padding-bottom:10px;border-bottom:1px solid var(--line);font-size:12.5px;color:var(--text-dim)}
.rx-stack{display:flex}
.rx-stack span{width:20px;height:20px;display:grid;place-items:center;margin-left:-5px;border-radius:50%;background:var(--panel);box-shadow:0 0 0 2px var(--panel);font-size:12px;line-height:1;animation:iconin .35s var(--ease) both}
.rx-stack span:first-child{margin-left:0}
.rx-com{margin-left:auto}
.rx-bar{display:flex;gap:4px;padding:4px 0}
.rx-like-wrap{position:relative;flex:1;display:flex}
.rx-act{flex:1;display:flex;align-items:center;justify-content:center;gap:7px;height:38px;font-size:13.5px;font-weight:600;color:var(--text-dim);transition:color .2s,background-color .2s,transform .2s}
.rx-act:hover{background:var(--chip);color:var(--text)}
.rx-em{display:none;font-size:17px;line-height:1}
.rx-like.on .rx-em{display:inline-block}
.rx-like.on .rx-ic{display:none}
.rx-like.pop{animation:rx-pop .5s cubic-bezier(.34,1.56,.64,1)}
@keyframes rx-pop{0%{transform:scale(1)}35%{transform:scale(.88)}70%{transform:scale(1.08)}100%{transform:scale(1)}}
.rx-tray{position:absolute;left:0;bottom:calc(100% + 6px);z-index:6;display:flex;gap:2px;padding:6px 8px;background:var(--panel);border:1px solid var(--icon-line);box-shadow:0 16px 36px -14px rgba(0,0,0,.4);opacity:0;visibility:hidden;transform:translateY(8px) scale(.9);transform-origin:20% 100%;transition:opacity .2s ease,transform .35s cubic-bezier(.34,1.56,.64,1),visibility 0s linear .35s}
.rx-tray.show{opacity:1;visibility:visible;transform:none;transition:opacity .2s ease,transform .35s cubic-bezier(.34,1.56,.64,1),visibility 0s}
.rx-e{position:relative;width:42px;height:42px;display:grid;place-items:center;font-size:27px;line-height:1;opacity:0;transform:translateY(12px) scale(.4);transition:transform .25s cubic-bezier(.34,1.56,.64,1)}
.rx-tray.show .rx-e{animation:rx-e-in .45s cubic-bezier(.34,1.56,.64,1) both;animation-delay:calc(var(--i) * 40ms)}
@keyframes rx-e-in{from{opacity:0;transform:translateY(12px) scale(.4)}to{opacity:1;transform:none}}
.rx-tray.show .rx-e:hover,.rx-tray.show .rx-e.act{transform:translateY(-8px) scale(1.38)}
.rx-tray.show .rx-e:hover,.rx-tray.show .rx-e.act{animation:none;opacity:1}
.rx-tip{position:absolute;bottom:calc(100% + 6px);left:50%;transform:translateX(-50%) translateY(4px);padding:3px 8px;border-radius:999px;background:var(--text);color:var(--panel);font-size:11px;font-weight:600;white-space:nowrap;opacity:0;transition:opacity .15s,transform .2s var(--ease);pointer-events:none}
.rx-e:hover .rx-tip,.rx-e.act .rx-tip{opacity:1;transform:translateX(-50%)}
.rx-fly{position:absolute;z-index:8;font-size:27px;line-height:1;pointer-events:none}
.rx-burst{position:absolute;width:6px;height:6px;border-radius:50%;pointer-events:none;z-index:7;animation:rx-burst .6s ease-out forwards}
@keyframes rx-burst{from{transform:translate(0,0) scale(1);opacity:1}to{transform:translate(var(--dx),var(--dy)) scale(.3);opacity:0}}
.rx{position:relative}

/* ---------- reactions ---------- */
{
  const rx = $('#rx'), tray = $('#rx-tray'), like = $('#rx-like'), wrap = $('#rx-wrap');
  const R = [['like','👍','Like'],['love','❤️','Love'],['celebrate','🎉','Celebrate'],['funny','😂','Funny'],['wow','😮','Wow'],['clap','👏','Applause']];
  const base = { like:14, love:6, celebrate:4 };
  let mine = null, openT = null, closeT = null, idx = -1;
  $('#rx-top').innerHTML = `${avatar('Maya Chen')}<div><div class="rx-n">Maya Chen</div><div class="rx-m">Design lead, 2h</div></div>`;
  tray.innerHTML = R.map((r, i) => `<button class="rx-e" role="menuitem" style="--i:${i}" data-r="${r[0]}" aria-label="${r[2]}">${r[1]}<span class="rx-tip">${r[2]}</span></button>`).join('');
  like.insertAdjacentHTML('afterbegin', `<span class="rx-ic">${ic('thumb_up','sm')}</span>`);
  function summary(){
    const counts = Object.assign({}, base); if (mine) counts[mine] = (counts[mine] || 0) + 1;
    const top = Object.entries(counts).sort((a, b) => b[1] - a[1]).slice(0, 3).map(e => R.find(r => r[0] === e[0])[1]);
    $('#rx-stack').innerHTML = top.map(e => `<span>${e}</span>`).join('');
    swapText($('#rx-count'), mine ? 'You, Oscar Lind and 23 others' : 'Oscar Lind and 23 others');
  }
  function openTray(o){
    clearTimeout(openT); clearTimeout(closeT);
    if (o && !tray.classList.contains('show')){ tray.classList.add('show'); idx = -1; Sound.play('open'); }
    if (!o){ tray.classList.remove('show'); $$('.rx-e', tray).forEach(e => e.classList.remove('act')); }
  }
  function burst(x, y, color){
    for (let k = 0; k < 8; k++){
      const p = document.createElement('span'); p.className = 'rx-burst';
      const a = k / 8 * Math.PI * 2, d = 22 + Math.random() * 10;
      p.style.left = (x - 3) + 'px'; p.style.top = (y - 3) + 'px'; p.style.background = color;
      p.style.setProperty('--dx', Math.cos(a) * d + 'px'); p.style.setProperty('--dy', Math.sin(a) * d + 'px');
      rx.appendChild(p); setTimeout(() => p.remove(), 650);
    }
  }
  function pick(key, fromEl){
    const r = R.find(x => x[0] === key);
    const rr = rx.getBoundingClientRect(), lr = like.getBoundingClientRect();
    const tx = lr.left - rr.left + 18, ty = lr.top - rr.top + 10;
    if (!reduce){
      const fly = document.createElement('span'); fly.className = 'rx-fly'; fly.textContent = r[1];
      fly.style.left = (lr.left - rr.left + lr.width / 2 - 14) + 'px'; fly.style.top = (lr.top - rr.top - 6) + 'px'; rx.appendChild(fly);
      fly.animate([
        { transform:'translateY(14px) scale(.4)', opacity:0 },
        { transform:'translateY(-26px) scale(1.5)', opacity:1, offset:.3 },
        { transform:'translate(-6px,-58px) scale(1.25) rotate(-8deg)', opacity:1, offset:.65 },
        { transform:'translate(4px,-92px) scale(1.1) rotate(6deg)', opacity:0 }
      ], { duration:1000, easing:'cubic-bezier(.22,1,.36,1)' }).onfinish = () => fly.remove();
    }
    openTray(false);
    setTimeout(() => {
      mine = key; like.classList.add('on'); like.dataset.r = key; $('#rx-em').textContent = r[1]; $('#rx-lbl').textContent = r[2];
      like.classList.remove('pop'); void like.offsetWidth; like.classList.add('pop');
      const col = { like:'#116ff8', love:'#ef4462', celebrate:'#22b07d', funny:'#f2b705', wow:'#f2b705', clap:'#8b6cf0' }[key];
      burst(tx + 6, ty + 8, col); summary(); Sound.play('done');
    }, 120);
  }
  wrap.addEventListener('mouseenter', () => { clearTimeout(closeT); openT = setTimeout(() => openTray(true), 380); });
  wrap.addEventListener('mouseleave', () => { clearTimeout(openT); closeT = setTimeout(() => openTray(false), 300); });
  let pressT = null;
  like.addEventListener('touchstart', () => { pressT = setTimeout(() => openTray(true), 380); }, { passive:true });
  like.addEventListener('touchend', () => clearTimeout(pressT));
  like.addEventListener('click', () => {
    if (tray.classList.contains('show') && idx < 0 && !mine){ /* open tray, plain click still likes */ }
    clearTimeout(openT); openTray(false);
    if (mine){ mine = null; like.classList.remove('on'); delete like.dataset.r; $('#rx-lbl').textContent = 'Like'; summary(); Sound.play('tick'); }
    else pick('like', null);
  });
  tray.addEventListener('click', e => { const b = e.target.closest('.rx-e'); if (b) pick(b.dataset.r, b); });
  tray.addEventListener('mouseover', e => { const b = e.target.closest('.rx-e'); if (b){ const i = +b.style.getPropertyValue('--i'); if (i !== idx){ idx = i; Sound.play('stream'); } } });
  like.addEventListener('keydown', e => {
    const es = $$('.rx-e', tray);
    if (e.key === 'ArrowUp'){ e.preventDefault(); openTray(true); idx = 0; es.forEach((x, i) => x.classList.toggle('act', i === idx)); }
    else if (tray.classList.contains('show') && (e.key === 'ArrowRight' || e.key === 'ArrowLeft')){ e.preventDefault(); idx = (idx + (e.key === 'ArrowRight' ? 1 : -1) + es.length) % es.length; es.forEach((x, i) => x.classList.toggle('act', i === idx)); Sound.play('tick'); }
    else if (tray.classList.contains('show') && e.key === 'Enter' && idx >= 0){ e.preventDefault(); pick(R[idx][0], es[idx]); }
    else if (e.key === 'Escape') openTray(false);
  });
  summary();
}
